/// <summary>
/// designed from AVA
/// </summary>
internal final class AVAPrintProdAttachment
{
    public ProdTable        prodTable;
    public    container     packedPrintDestination;

}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_prodTable">_prodTable</param>
void new(ProdTable      _prodTable)
{
    prodTable = _prodTable;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_packedPrintDesctination">_packedPrintDesctination</param>
/// <returns>parmPackedPrintDestination</returns>
container parmPackedPrintDestination(container  _packedPrintDesctination = packedPrintDestination)
{
    packedPrintDestination  = _packedPrintDesctination;
    return packedPrintDestination;
}

/// <summary>
/// designed from AVA
/// </summary>
void printAttachments()
{
    DocuRef         docuRef;
    DocuValue       docuValue;
    DocuType        docuType;

    while select docuRef
        where docuRef.RefTableId == prodTable.TableId 
           && docuRef.RefRecId   == prodTable.RecId
                join   docuValue
                    where docuValue.RecId == docuRef.ValueRecId
                join docuType
                    where docuType.TypeId == docuRef.TypeId
                       && docuType.TypeGroup == DocuTypeGroup::File
    {
        container fileCon = DocumentManagement::getAttachmentAsContainer(docuRef);
        var stream = Binary::constructFromContainer(fileCon).getMemoryStream();

        AVASrsReportPrintFromStream::printStream(stream,docuValue.fileName,packedPrintDestination);
    }

}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_prodTable">_prodTable</param>
/// <param name = "_printSettings">_printSettings</param>
public static void constructFromProduction(ProdTable    _prodTable, container       _printSettings = conNull())
{
    AVAPrintProdAttachment      printProdAttachment = new AVAPrintProdAttachment(_prodTable);
    printProdAttachment.parmPackedPrintDestination(_printSettings);
    printProdAttachment.printAttachments();
}
